<script setup lang="ts">import { computed,onMounted } from 'vue'; import PageHeader from '../components/PageHeader.vue'; import MetricCard from '../components/MetricCard.vue'; import CommandFeedback from '../components/CommandFeedback.vue'; import { useProjectStore } from '../stores/projectStore'; const s=useProjectStore(); const x=computed(()=>s.marketStrategy); const state=computed(()=>s.commandState('market-pulse')); onMounted(()=>void s.loadMarket()); async function refresh(){await s.runCommand('market-pulse',{type:'market_pulse_refresh'});await s.loadMarket(true)}</script><template><div v-if="x" class="page"><PageHeader title="市场与平台策略" subtitle="市场证据与作品权威分离，只用于机会判断和授权范围内的策略校准。"><button class="btn primary" @click="refresh">重新复核市场</button></PageHeader><CommandFeedback :state="state"/><div class="metric-grid section"><MetricCard label="目标平台" :value="x.targetPlatform" :note="x.platformPolicyVersion"/><MetricCard label="策略置信度" :value="`${x.confidence}%`" :note="`快照 ${x.snapshotCollectedAt}`"/><MetricCard label="最近复核" :value="x.lastPulseAt" :note="`下次：${x.nextReview}`"/><MetricCard label="当前策略" :value="x.strategyTitle" :note="x.readerPromise"/></div><div class="market-grid section"><article v-for="m in x.opportunities" :key="m.id" class="market-card"><span class="badge">{{ m.kind }}</span><h3>{{ m.title }}</h3><div class="market-meta">{{ m.platform }} · {{ m.direction }}</div><div class="score-grid"><div class="score"><b>{{ m.demand }}</b><span>需求</span></div><div class="score"><b>{{ m.growth }}</b><span>增长</span></div><div class="score"><b>{{ m.originalitySpace }}</b><span>差异空间</span></div></div><p>{{ m.recommendWhy }}</p><small class="muted">{{ m.source }} · {{ m.collectedAt }}</small></article></div></div></template>
